SET client_encoding = 'UTF8'; -- UTF-8 file: import with psql -f, never through a PowerShell pipe (see scripts/seeds/README.md)
UPDATE questions SET subcategory_id=1, stem='Under the 1987 Philippine Constitution, which branch of government is primarily responsible for making laws?', options='["Executive Branch","Legislative Branch","Judicial Branch","Constitutional Commissions"]'::jsonb, correct_option=1, explanation='Article VI vests legislative power in Congress (Senate and House of Representatives). The Executive enforces laws; the Judiciary interprets them.', updated_at=NOW() WHERE id=457;
UPDATE questions SET subcategory_id=1, stem='How many years is the term of office of the President of the Philippines?', options='["Four years, with one reelection allowed","Five years, without reelection","Six years, without reelection","Six years, with one reelection allowed"]'::jsonb, correct_option=2, explanation='Article VII, Section 4: the President serves a single term of six years and is not eligible for any reelection.', updated_at=NOW() WHERE id=458;
UPDATE questions SET subcategory_id=1, stem='Who has the power to declare martial law in the Philippines?', options='["The Congress alone","The Supreme Court","The President, for a period not exceeding 60 days","The Commission on Human Rights"]'::jsonb, correct_option=2, explanation='Article VII, Section 18: the President may place the Philippines under martial law for a period not exceeding 60 days, subject to congressional and judicial review.', updated_at=NOW() WHERE id=459;
UPDATE questions SET subcategory_id=1, stem='The Bill of Rights in the 1987 Constitution is found in which article?', options='["Article II","Article III","Article IV","Article V"]'::jsonb, correct_option=1, explanation='Article III is the Bill of Rights. Article II is Declaration of Principles; Article IV is Citizenship; Article V is Suffrage.', updated_at=NOW() WHERE id=460;
UPDATE questions SET subcategory_id=1, stem='Which constitutional commission is tasked with administering the civil service?', options='["Commission on Elections (COMELEC)","Commission on Audit (COA)","Civil Service Commission (CSC)","Commission on Human Rights (CHR)"]'::jsonb, correct_option=2, explanation='Article IX-B establishes the Civil Service Commission as the central personnel agency of the government.', updated_at=NOW() WHERE id=461;
UPDATE questions SET subcategory_id=2, stem='Republic Act No. 6713 is also known as the:', options='["Anti-Graft and Corrupt Practices Act","Code of Conduct and Ethical Standards for Public Officials and Employees","Ombudsman Act","Freedom of Information Act"]'::jsonb, correct_option=1, explanation='R.A. 6713 is the Code of Conduct and Ethical Standards for Public Officials and Employees. Anti-graft is mainly R.A. 3019.', updated_at=NOW() WHERE id=462;
UPDATE questions SET subcategory_id=2, stem='Under R.A. 6713, which of the following is a prohibited act for public officials?', options='["Attending public consultations","Soliciting or accepting gifts in the course of official duties","Filing a statement of assets and liabilities","Reporting graft to the Ombudsman"]'::jsonb, correct_option=1, explanation='Section 7 of R.A. 6713 prohibits solicitation or acceptance of gifts in the course of official duties, among other prohibited acts.', updated_at=NOW() WHERE id=463;
UPDATE questions SET subcategory_id=2, stem='Public officials and employees are required to file their Statement of Assets, Liabilities and Net Worth (SALN):', options='["Only upon assumption of office","Only upon resignation or retirement","Upon assumption of office, annually thereafter, and upon separation from service","Every five years only"]'::jsonb, correct_option=2, explanation='R.A. 6713 requires SALN filing upon assumption, every year thereafter, and upon separation from the service.', updated_at=NOW() WHERE id=464;
UPDATE questions SET subcategory_id=3, stem='Which international document is the foundation of modern human rights standards?', options='["Geneva Conventions only","Universal Declaration of Human Rights (UDHR)","Kyoto Protocol","Treaty of Versailles"]'::jsonb, correct_option=1, explanation='The Universal Declaration of Human Rights (1948) sets out fundamental human rights to be universally protected.', updated_at=NOW() WHERE id=465;
UPDATE questions SET subcategory_id=4, stem='Which of the following is a core Philippine environmental law?', options='["R.A. 6713 (Code of Conduct) only","R.A. 8749 (Clean Air Act)","The Labor Code","The Civil Code alone"]'::jsonb, correct_option=1, explanation='R.A. 8749 (Clean Air Act) is a major environmental statute, alongside R.A. 9003 (Ecological Solid Waste Management Act) and the EIS system under P.D. 1586.', updated_at=NOW() WHERE id=466;
UPDATE questions SET subcategory_id=5, stem='Choose the word that is closest in meaning to METICULOUS.', options='["Careless","Careful and precise","Loud","Temporary"]'::jsonb, correct_option=1, explanation='Meticulous means showing great attention to detail; careful and precise.', updated_at=NOW() WHERE id=467;
UPDATE questions SET subcategory_id=5, stem='Which word is an antonym of BENEVOLENT?', options='["Kind","Generous","Malevolent","Charitable"]'::jsonb, correct_option=2, explanation='Benevolent means kind or well-meaning; malevolent means wishing harm — the opposite.', updated_at=NOW() WHERE id=468;
UPDATE questions SET subcategory_id=6, stem='The committee members agreed that the proposal was _____, so they voted to adopt it immediately.', options='["untenable","feasible","ambiguous","obsolete"]'::jsonb, correct_option=1, explanation='Feasible means practicable or workable. Untenable means not defensible; obsolete means outdated.', updated_at=NOW() WHERE id=469;
UPDATE questions SET subcategory_id=7, stem='Identify the sentence with a grammatical error.', options='["Neither of the applicants was qualified.","The data are being reviewed by the panel.","Each of the employees have submitted a report.","She and I are attending the seminar."]'::jsonb, correct_option=2, explanation='"Each" is singular, so the verb should be "has," not "have."', updated_at=NOW() WHERE id=470;
UPDATE questions SET subcategory_id=11, stem='Book is to Library as Painting is to _____.', options='["Artist","Museum","Frame","Brush"]'::jsonb, correct_option=1, explanation='A book is kept or displayed in a library; a painting is kept or displayed in a museum.', updated_at=NOW() WHERE id=471;
UPDATE questions SET subcategory_id=15, stem='What is 15% of 240?', options='["24","30","36","48"]'::jsonb, correct_option=2, explanation='0.15 × 240 = 36.', updated_at=NOW() WHERE id=472;
UPDATE questions SET subcategory_id=16, stem='What is the next number in the sequence: 2, 6, 12, 20, 30, _____?', options='["36","40","42","48"]'::jsonb, correct_option=2, explanation='Differences increase by 2: +4, +6, +8, +10, then +12 → 30+12=42. (Or n(n+1): 6×7=42.)', updated_at=NOW() WHERE id=473;
UPDATE questions SET subcategory_id=17, stem='A clerk can process 40 applications in 5 hours. At the same rate, how many applications can the clerk process in 8 hours?', options='["56","60","64","72"]'::jsonb, correct_option=2, explanation='Rate = 40/5 = 8 applications per hour. In 8 hours: 8 × 8 = 64.', updated_at=NOW() WHERE id=474;
UPDATE questions SET subcategory_id=13, stem='All civil service eligibles must pass an examination. Maria is a civil service eligible. Which conclusion follows?', options='["Maria failed the examination.","Maria passed an examination.","Maria works in government.","Maria is a lawyer."]'::jsonb, correct_option=1, explanation='If all eligibles must pass an exam and Maria is eligible, she must have passed an examination. Employment or profession is not stated.', updated_at=NOW() WHERE id=475;
UPDATE questions SET subcategory_id=10, stem='According to a passage: "Transparency in government builds public trust." Which statement best restates the main idea?', options='["Government should keep all records secret.","Openness in government helps citizens trust public institutions.","Public trust is unrelated to government policy.","Only private companies need transparency."]'::jsonb, correct_option=1, explanation='The sentence links transparency (openness) with building public trust in government.', updated_at=NOW() WHERE id=476;
